<?php
require_once __DIR__.'/shared.php';$db=acadDb();$id=filter_var($_GET['id']??0,FILTER_VALIDATE_INT,['options'=>['min_range'=>1]]);
if(!$id){$rows=$db->query("SELECT a.*,p.program_code,ap.academic_year,ap.semester FROM academic_approval_requests a JOIN programs p ON p.program_id=a.program_id JOIN academic_periods ap ON ap.academic_period_id=a.academic_period_id ORDER BY FIELD(a.status,'PENDING_REVIEW','RETURNED','APPROVED','PUBLISHED','SUPERSEDED'),a.approval_id DESC LIMIT 250")->fetchAll();acadLayout('Approval Center');echo '<h1>Schedule Approval Center</h1><p>Choose a submission to inspect the actual saved timetable and its decision history.</p><div class="panel scroll"><table><tr><th>Request</th><th>Program</th><th>Period</th><th>Type</th><th>Status</th><th></th></tr>';foreach($rows as $r)echo '<tr><td>#'.(int)$r['approval_id'].'</td><td>'.acadH($r['program_code']).'</td><td>'.acadH($r['academic_year']).' / '.(int)$r['semester'].'</td><td>'.acadH($r['schedule_type']).'</td><td><span class="tag '.acadH($r['status']).'">'.acadH($r['status']).'</span></td><td><a class="btn secondary" href="review.php?id='.(int)$r['approval_id'].'">Open</a></td></tr>';if(!$rows)echo '<tr><td colspan="6">No submitted schedules yet.</td></tr>';echo '</table></div>';acadEnd();exit;}
$q=$db->prepare("SELECT a.*,p.program_code,ap.academic_year,ap.semester,u.username AS submitter FROM academic_approval_requests a JOIN programs p ON p.program_id=a.program_id JOIN academic_periods ap ON ap.academic_period_id=a.academic_period_id JOIN auth_users u ON u.user_id=a.submitted_by WHERE a.approval_id=?");$q->execute([$id]);$a=$q->fetch();if(!$a){http_response_code(404);exit('Review request not found.');}
$type=$a['schedule_type'];$batch=(int)($type==='CLASS'?$a['class_batch_id']:$a['exam_batch_id']);$current=acadBatch($db,$type,$batch);$snapshotOk=false;try{$snapshotOk=$current&&$current['status']==='ACTIVE'&&hash_equals($a['snapshot_hash'],acadFingerprint($db,$type,$batch));}catch(Throwable $e){error_log($e->getMessage());}
if($type==='CLASS'){$q=$db->prepare("SELECT sec.section_code,s.subject_code,s.subject_title,t.teacher_name,r.room_name,m.delivery_mode,m.day_of_week,m.start_time,m.end_time FROM schedule_meetings m JOIN section_subjects ss ON ss.section_subject_id=m.section_subject_id JOIN sections sec ON sec.section_id=ss.section_id JOIN subjects s ON s.subject_id=ss.subject_id JOIN teachers t ON t.teacher_id=m.teacher_id LEFT JOIN rooms r ON r.room_id=m.room_id WHERE m.batch_id=? ORDER BY sec.section_code,FIELD(m.day_of_week,'Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'),m.start_time");$headers=['Section','Subject','Title','Teacher','Room','Mode','Day','Start','End'];}else{$q=$db->prepare("SELECT sec.section_code,s.subject_code,s.subject_title,t.teacher_name,r.room_name,em.exam_day,em.exam_date,em.start_time,em.end_time FROM exam_meetings em JOIN section_subjects ss ON ss.section_subject_id=em.section_subject_id JOIN sections sec ON sec.section_id=ss.section_id JOIN subjects s ON s.subject_id=ss.subject_id JOIN teachers t ON t.teacher_id=em.proctor_id LEFT JOIN rooms r ON r.room_id=em.room_id WHERE em.exam_batch_id=? ORDER BY sec.section_code,em.exam_day,em.start_time");$headers=['Section','Subject','Title','Proctor','Room','Exam Day','Date','Start','End'];}
$q->execute([$batch]);$meetings=$q->fetchAll();$h=$db->prepare("SELECT x.*,u.username FROM academic_approval_actions x JOIN auth_users u ON u.user_id=x.actor_id WHERE x.approval_id=? ORDER BY x.action_id DESC");$h->execute([$id]);$history=$h->fetchAll();acadLayout('Schedule Review');?>
<div class="eyebrow">APPROVAL REQUEST #<?= $id ?></div><h1><?=acadH($a['program_code'])?> — <?=acadH($type)?> timetable</h1><p><?=acadH($a['academic_year'])?> · Semester <?=(int)$a['semester']?> · Submitted by <?=acadH($a['submitter'])?> · Batch #<?=$batch?></p>
<div class="panel"><div class="actions"><span class="tag <?=acadH($a['status'])?>"><?=acadH($a['status'])?></span><span class="tag"><?=count($meetings)?> meetings</span><span class="tag"><?= $snapshotOk?'Stored snapshot matches':'Snapshot changed or batch inactive' ?></span></div><p><strong>Important:</strong> Matching a stored snapshot is an integrity check, not a comprehensive conflict audit. Approve only after independently checking all institutional scheduling rules and conflicts. This test build does not certify a zero-conflict timetable. Rejecting this request requires Admin to generate and save a brand-new batch before sending a replacement request.</p><?php if($a['status']==='PENDING_REVIEW'&&$snapshotOk):?><form method="post" action="action.php"><input type="hidden" name="csrf_token" value="<?=acadH(authCsrf())?>"><input type="hidden" name="id" value="<?=$id?>"><label for="remarks">Decision remarks (mandatory when rejecting)</label><textarea id="remarks" name="remarks" maxlength="3000" placeholder="Document validation and any required corrections"></textarea><div class="actions block"><button type="submit" name="decision" value="APPROVED" onclick="return confirm('Approve and officially publish this exact timetable version?')">Approve &amp; Publish</button><button class="warn" type="submit" name="decision" value="RETURNED" onclick="return confirm('Reject this timetable? Admin must generate and save a NEW timetable before submitting again.')">Reject Schedule</button></div></form><?php endif;?></div>
<div class="panel"><div class="actions no-print"><h2>Saved timetable details</h2><button class="secondary" onclick="window.print()">Print Review Copy</button></div><div class="print-head"><h2>BESTLINK COLLEGE OF THE PHILIPPINES — SCHEDULE REVIEW COPY</h2></div><div class="scroll"><table><tr><?php foreach($headers as $col):?><th><?=acadH($col)?></th><?php endforeach;?></tr><?php foreach($meetings as $m):?><tr><?php foreach(array_values($m) as $v):?><td><?=acadH($v??'—')?></td><?php endforeach;?></tr><?php endforeach;?></table></div></div><div class="panel"><h2>Decision history</h2><div class="scroll"><table><tr><th>Action</th><th>Actor</th><th>Remarks</th><th>Date</th></tr><?php foreach($history as $r):?><tr><td><?=acadH($r['action_type'])?></td><td><?=acadH($r['username'])?></td><td><?=acadH($r['remarks']??'')?></td><td><?=acadH($r['created_at'])?></td></tr><?php endforeach;?></table></div></div><?php acadEnd();